import { PlaneGeometry, Object3D, Mesh } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const container = new Object3D();

  // Load texture from cache
  const textureResource = ctx.textureLoader.load(config.assets.imageUrl);

  // Atlas region dimensions: 512x320 → aspect ratio 1.6:1
  const aspectRatio = 512 / 320;

  // Create plane geometry with correct aspect ratio
  const geometry = new PlaneGeometry(aspectRatio, 1);

  // Create material with TSL texture node
  const material = new MeshBasicNodeMaterial({
    map: texture(textureResource),
    toneMapped: false,
  });

  // Create mesh
  const mesh = new Mesh(geometry, material);

  // Apply transforms from config
  const position = config.position || [0, 0, 0];
  const rotation = config.rotation || [0, 0, 0];
  const scale = config.scale || [1, 1, 1];

  mesh.position.set(position[0], position[1], position[2]);
  mesh.rotation.set(rotation[0], rotation[1], rotation[2]);
  mesh.scale.set(scale[0], scale[1], scale[2]);

  container.add(mesh);

  // Cleanup resources
  container.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
  };

  return container;
}
